content.css:
@font-face {
  font-family: 'Plus Jakarta Sans';
  font-style: normal;
  font-weight: 200 800;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2-variations');
}
.visual-root {
  display: flex;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 8px;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  overflow: hidden;
  background: transparent;
  font-weight: 600;
  font-variation-settings: "wght" 600;
  --ds-color-ink: #131B33;
  --ds-color-surface: #FFFFFF;
  --ds-color-line: #DDE2F0;
  --ds-color-blue: #0A4EE4;
  --ds-shadow-card: 0 1px 2px rgba(19, 27, 51, 0.04), 0 8px 24px -12px rgba(19, 27, 51, 0.18);
}
.visual-root.visual-root--popup-open {
  overflow: visible;
}
.visual-root.visual-root--bottom {
  align-items: flex-end;
  align-content: flex-end;
}
.filter-anchor {
  position: relative;
  display: inline-block;
  max-width: 100%;
  min-width: 0;
}
.filter-anchor--open {
  z-index: 5;
}
.filter-pill-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.filter-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 44px;
  padding: 0 18px;
  box-sizing: border-box;
  border-radius: 999px;
  border: 1px solid var(--ds-color-line);
  background: transparent;
  color: var(--ds-color-ink);
  font-size: 0.92rem;
  cursor: pointer;
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: border-color 0.1s ease-in-out, background-color 0.1s ease-in-out;
}
.filter-pill:hover,
.filter-pill:focus-visible {
  border-color: var(--ds-color-blue);
}
.filter-pill:focus-visible {
  outline: 2px solid var(--ds-color-blue);
  outline-offset: 2px;
}
.filter-pill--active {
  border-color: var(--ds-color-blue);
  background: var(--ds-color-blue);
  color: #fff;
}
.filter-pill-clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.22);
  font-size: 0.78rem;
  line-height: 1;
  flex: 0 0 auto;
}
.filter-pill-clear:hover {
  background: rgba(255, 255, 255, 0.34);
}
.filter-popup {
  position: absolute;
  top: 100%;
  left: 0;
  margin-top: 6px;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  min-width: 200px;
  max-width: 280px;
  box-sizing: border-box;
  padding: 6px;
  gap: 4px;
  border-radius: 14px;
  border: 1px solid var(--ds-color-line);
  background: var(--ds-color-surface);
  box-shadow: var(--ds-shadow-card);
  font-family: inherit;
  color: var(--ds-color-ink);
  font-weight: 400;
  font-variation-settings: "wght" 400;
}
.filter-popup.filter-popup--above {
  top: auto;
  bottom: 100%;
  margin-top: 0;
  margin-bottom: 6px;
}
.filter-popup.filter-popup--right {
  left: auto;
  right: 0;
}
.filter-popup-search {
  box-sizing: border-box;
  width: 100%;
  height: 34px;
  padding: 0 10px;
  border-radius: 8px;
  border: 1px solid var(--ds-color-line);
  background: transparent;
  color: var(--ds-color-ink);
  font-family: inherit;
  font-size: 0.86rem;
  flex: 0 0 auto;
}
.filter-popup-search::placeholder {
  color: var(--ds-color-ink);
  opacity: 0.5;
}
.filter-popup-search:focus-visible {
  outline: 2px solid var(--ds-color-blue);
  outline-offset: -1px;
}
.filter-popup-clear-all {
  display: none;
  flex: 0 0 auto;
  width: 100%;
  box-sizing: border-box;
  padding: 6px 8px;
  border: none;
  border-radius: 8px;
  background: transparent;
  text-align: left;
  font-family: inherit;
  font-size: 0.82rem;
  color: var(--ds-color-blue);
  cursor: pointer;
  font-weight: 600;
  font-variation-settings: "wght" 600;
}
.filter-popup-clear-all:hover,
.filter-popup-clear-all:focus-visible {
  background: var(--ds-color-line);
  outline: none;
}
.filter-popup-rows {
  max-height: var(--popup-rows-max-height, 260px);
  overflow-y: auto;
  flex: 0 1 auto;
  scrollbar-width: thin;
  scrollbar-color: var(--ds-color-line) transparent;
}
.filter-popup-rows::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
.filter-popup-rows::-webkit-scrollbar-track {
  background: transparent;
}
.filter-popup-rows::-webkit-scrollbar-thumb {
  background-color: var(--ds-color-line);
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
.filter-popup-rows::-webkit-scrollbar-thumb:hover {
  background-color: var(--ds-color-ink);
}
.filter-popup-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  box-sizing: border-box;
  padding: 8px 12px;
  border-radius: 8px;
  background: transparent;
  border: none;
  text-align: left;
  font-family: inherit;
  font-size: 0.9rem;
  color: var(--ds-color-ink);
  cursor: pointer;
}
.filter-popup-item:hover,
.filter-popup-item:focus-visible {
  background: var(--ds-color-line);
  outline: none;
}
.filter-popup-item.filter-popup-item--selected .filter-popup-item-label {
  font-weight: 700;
  font-variation-settings: "wght" 700;
  color: var(--ds-color-blue);
}
.filter-popup-item.filter-popup-item--empty {
  color: var(--ds-color-ink);
  opacity: 0.6;
  cursor: default;
}
.filter-popup-item.filter-popup-item--empty:hover {
  background: transparent;
}
.filter-popup-item-label {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.filter-popup-checkbox {
  flex: 0 0 auto;
  width: 16px;
  height: 16px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  border: 1px solid var(--ds-color-line);
  font-size: 0.7rem;
  line-height: 1;
  color: #fff;
}
.filter-popup-item--selected .filter-popup-checkbox {
  background: var(--ds-color-blue);
  border-color: var(--ds-color-blue);
}
.empty-state {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: var(--ds-color-ink);
  opacity: 0.6;
  font-size: 0.82rem;
  text-align: center;
  padding: 8px;
  box-sizing: border-box;
}
